import (
	"fmt"
)

func main() {
	var a, ta, b, tb int
	var time string

	fmt.Scan(&a, &ta)
	fmt.Scan(&b, &tb)
	fmt.Scan(&time)

	var hour, minute int
	fmt.Sscanf(time, "%d:%d", &hour, &minute)

	start := hour*60 + minute
	finish := start + ta
	count := 0

